mapper.select:
        select
IDOS_CLASS_NAMEREMARKSTATUSDELETE_FLAGCREATE_TIMECREATE_USERUPDATE_TIMEUPDATE_USER
        from os_class
        
            
                and ID = #{id}
            
            
                and OS_CLASS_NAME = #{osClassName}
            
            
                and REMARK = #{remark}
            
            
                and STATUS = #{status}
            
            
                and DELETE_FLAG = #{deleteFlag}
            
            
                and CREATE_TIME = #{createTime}
            
            
                and CREATE_USER = #{createUser}
            
            
                and UPDATE_TIME = #{updateTime}
            
            
                and UPDATE_USER = #{updateUser}
            
        
        limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from os_class

    
        and ID = #{id}
    
    
        and OS_CLASS_NAME = #{osClassName}
    
    
        and REMARK = #{remark}
    
    
        and STATUS = #{status}
    
    
        and DELETE_FLAG = #{deleteFlag}
    
    
        and CREATE_TIME = #{createTime}
    
    
        and CREATE_USER = #{createUser}
    
    
        and UPDATE_TIME = #{updateTime}
    
    
        and UPDATE_USER = #{updateUser}
